.version 7.8
.target sm_89
.address_size 64
// Structural rewrite: cooperative CTA-tiled convolution with shared-memory staging.
// Each CTA computes a 16x16 output tile for one (n, co) pair. Input halo tile
// (18x18) is staged in shared memory in chunks of 8 input channels together with
// the corresponding 8*9 weights, so neighboring outputs reuse activations/weights
// from shared memory instead of repeatedly reloading them from global memory.
.visible .entry conv2d_k3_s1_p0_f32(
    .param .u64 p_in,
    .param .u64 p_wt,
    .param .u64 p_out,
    .param .u32 p_N,
    .param .u32 p_C,
    .param .u32 p_H,
    .param .u32 p_W,
    .param .u32 p_CO,
    .param .u32 p_HO,
    .param .u32 p_WO
)
{
    .reg .pred %p<8>;
    .reg .u32 %r<48>;
    .reg .u64 %rd<32>;
    .reg .f32 %f<16>;
    // smem: 2592 floats input tile (8ch x 18x18) + 72 floats weights
    .shared .align 16 .b8 smem_buf[10656];
    ld.param.u64 %rd1, [p_in];
    ld.param.u64 %rd2, [p_wt];
    ld.param.u64 %rd3, [p_out];
    ld.param.u32 %r20, [p_N];
    ld.param.u32 %r12, [p_C];
    ld.param.u32 %r13, [p_H];
    ld.param.u32 %r14, [p_W];
    ld.param.u32 %r15, [p_CO];
    ld.param.u32 %r16, [p_HO];
    ld.param.u32 %r17, [p_WO];
    mov.u32 %r1, %tid.x;
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ctaid.y;
    mov.u32 %r4, %ctaid.z;
    and.b32 %r5, %r1, 15;       // ox
    shr.u32 %r6, %r1, 4;        // oy
    shl.b32 %r7, %r2, 4;        // x0
    shl.b32 %r8, %r3, 4;        // y0
    add.u32 %r9, %r7, %r5;      // out_x
    add.u32 %r10, %r8, %r6;     // out_y
    div.u32 %r21, %r4, %r15;    // n
    mul.lo.u32 %r22, %r21, %r15;
    sub.u32 %r23, %r4, %r22;    // co
    cvt.u64.u32 %rd4, %r12;     // C
    cvt.u64.u32 %rd5, %r13;     // H
    cvt.u64.u32 %rd6, %r14;     // W
    cvt.u64.u32 %rd7, %r16;     // HO
    cvt.u64.u32 %rd8, %r17;     // WO
    cvt.u64.u32 %rd9, %r21;     // n
    cvt.u64.u32 %rd10, %r23;    // co
    mov.u64 %rd20, smem_buf;    // shared base address
    // weight global base for this co: wt + co*C*9*4
    mul.lo.u64 %rd11, %rd10, %rd4;
    mul.lo.u64 %rd11, %rd11, 9;
    shl.b64 %rd11, %rd11, 2;
    add.u64 %rd11, %rd11, %rd2;
    // input global base for this n: in + n*C*H*W*4
    mul.lo.u64 %rd12, %rd9, %rd4;
    mul.lo.u64 %rd12, %rd12, %rd5;
    mul.lo.u64 %rd12, %rd12, %rd6;
    shl.b64 %rd12, %rd12, 2;
    add.u64 %rd12, %rd12, %rd1;
    mov.f32 %f1, 0f00000000;    // accumulator
    mov.u32 %r24, 0;            // c0
$CHUNK_LOOP:
    setp.lt.u32 %p1, %r24, %r12;
    @!%p1 bra $CHUNK_DONE;
    // ---- stage input tile: k = tid; k < 2592; k += 256
    mov.u32 %r25, %r1;
$STG_LOOP:
    setp.lt.u32 %p2, %r25, 2592;
    @!%p2 bra $STG_DONE;
    div.u32 %r26, %r25, 324;    // c_sub
    mul.lo.u32 %r27, %r26, 324;
    sub.u32 %r28, %r25, %r27;   // rem
    div.u32 %r29, %r28, 18;     // row
    mul.lo.u32 %r30, %r29, 18;
    sub.u32 %r31, %r28, %r30;   // col
    add.u32 %r32, %r24, %r26;   // c  = c0 + c_sub
    add.u32 %r33, %r8, %r29;    // iy = y0 + row
    add.u32 %r34, %r7, %r31;    // ix = x0 + col
    setp.lt.u32 %p3, %r32, %r12;
    setp.lt.u32 %p4, %r33, %r13;
    setp.lt.u32 %p5, %r34, %r14;
    and.pred %p6, %p3, %p4;
    and.pred %p6, %p6, %p5;
    cvt.u64.u32 %rd13, %r32;
    cvt.u64.u32 %rd14, %r33;
    cvt.u64.u32 %rd15, %r34;
    mul.lo.u64 %rd16, %rd13, %rd5;
    add.u64 %rd16, %rd16, %rd14;
    mul.lo.u64 %rd16, %rd16, %rd6;
    add.u64 %rd16, %rd16, %rd15;
    shl.b64 %rd16, %rd16, 2;
    add.u64 %rd16, %rd16, %rd12;
    mov.f32 %f2, 0f00000000;
    @%p6 ld.global.f32 %f2, [%rd16];
    cvt.u64.u32 %rd17, %r25;
    shl.b64 %rd17, %rd17, 2;
    add.u64 %rd17, %rd17, %rd20;
    st.shared.f32 [%rd17], %f2;
    add.u32 %r25, %r25, 256;
    bra $STG_LOOP;
$STG_DONE:
    // ---- stage weights for this chunk: threads 0..71 load one float each
    setp.lt.u32 %p2, %r1, 72;
    @!%p2 bra $WT_DONE;
    div.u32 %r26, %r1, 9;
    add.u32 %r32, %r24, %r26;   // c = c0 + tid/9
    setp.lt.u32 %p3, %r32, %r12;
    mul.lo.u32 %r27, %r24, 9;
    add.u32 %r27, %r27, %r1;    // c0*9 + j
    cvt.u64.u32 %rd13, %r27;
    shl.b64 %rd13, %rd13, 2;
    add.u64 %rd13, %rd13, %rd11;
    mov.f32 %f2, 0f00000000;
    @%p3 ld.global.f32 %f2, [%rd13];
    cvt.u64.u32 %rd17, %r1;
    shl.b64 %rd17, %rd17, 2;
    add.u64 %rd17, %rd17, %rd20;
    add.u64 %rd17, %rd17, 10368;
    st.shared.f32 [%rd17], %f2;
$WT_DONE:
    bar.sync 0;
    // ---- compute: 8 staged channels x 9 taps from shared memory
    mul.lo.u32 %r35, %r6, 18;
    add.u32 %r35, %r35, %r5;    // oy*18 + ox (floats)
    cvt.u64.u32 %rd21, %r35;
    mul.lo.u64 %rd21, %rd21, 4;
    add.u64 %rd21, %rd21, %rd20;  // &sm_in[0][oy][ox]
    add.u64 %rd22, %rd20, 10368;  // &sm_w[0]
    mov.u32 %r36, 0;            // c_sub
$CS_LOOP:
    setp.lt.u32 %p2, %r36, 8;
    @!%p2 bra $CS_DONE;
    mul.lo.u32 %r37, %r36, 1296;  // c_sub*324*4
    cvt.u64.u32 %rd23, %r37;
    add.u64 %rd24, %rd21, %rd23;  // in ptr
    mul.lo.u32 %r38, %r36, 36;    // c_sub*9*4
    cvt.u64.u32 %rd25, %r38;
    add.u64 %rd26, %rd22, %rd25;  // wt ptr
    ld.shared.f32 %f2, [%rd24 + 0];
    ld.shared.f32 %f3, [%rd26 + 0];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    ld.shared.f32 %f2, [%rd24 + 4];
    ld.shared.f32 %f3, [%rd26 + 4];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    ld.shared.f32 %f2, [%rd24 + 8];
    ld.shared.f32 %f3, [%rd26 + 8];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    ld.shared.f32 %f2, [%rd24 + 72];
    ld.shared.f32 %f3, [%rd26 + 12];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    ld.shared.f32 %f2, [%rd24 + 76];
    ld.shared.f32 %f3, [%rd26 + 16];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    ld.shared.f32 %f2, [%rd24 + 80];
    ld.shared.f32 %f3, [%rd26 + 20];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    ld.shared.f32 %f2, [%rd24 + 144];
    ld.shared.f32 %f3, [%rd26 + 24];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    ld.shared.f32 %f2, [%rd24 + 148];
    ld.shared.f32 %f3, [%rd26 + 28];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    ld.shared.f32 %f2, [%rd24 + 152];
    ld.shared.f32 %f3, [%rd26 + 32];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    add.u32 %r36, %r36, 1;
    bra $CS_LOOP;
$CS_DONE:
    bar.sync 0;
    add.u32 %r24, %r24, 8;
    bra $CHUNK_LOOP;
