    add.u64 %rd16, %rd16, %rd14;
    mul.lo.u64 %rd16, %rd16, %rd8;
    add.u64 %rd16, %rd16, %rd15;
    shl.b64 %rd16, %rd16, 2;
    add.u64 %rd16, %rd16, %rd3;
