        self.conv2d = nn.Conv2d(in_channels, out_channels, (kernel_size, kernel_size), stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda or x.dtype != torch.float32:
            raise RuntimeError("PTX kernel expects CUDA float32 input")
        if self.conv2d.kernel_size != (3, 3) or self.conv2d.stride != (1, 1) or self.conv2d.padding != (0, 0) or self.conv2d.dilation != (1, 1) or self.conv2d.groups != 1 or self.conv2d.bias is not None:
            raise RuntimeError("specialized PTX kernel supports only 3x3 stride=1 padding=0 dilation=1 groups=1 no-bias convolution")

