        C = x.size(1)
        H = x.size(2)
        W = x.size(3)
        CO = self.conv2d.out_channels
        HO = H - 2
        WO = W - 2
        if C != self.conv2d.in_channels or HO <= 0 or WO <= 0:
            raise RuntimeError("invalid convolution dimensions")

        output = torch.empty((N, CO, HO, WO), device=x.device, dtype=x.dtype)
        module = _get_ptx_module()
        module.launch(
            "conv2d_k3_s1_p0_f32",
            grid=((WO + 15) // 16, (HO + 15) // 16, N * CO),
            block=(256, 1, 1),
            arguments=[x, self.conv2d.weight, output, i32(N), i32(C), i32(H), i32(W), i32(CO), i32(HO), i32(WO)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output

